def search(notes, query, config):
    def normalize(value):
        text = str(value)
        return text if config['case_sensitive'] else text.casefold()

    needle = normalize(query)
    matches = []
    for note in notes:
        if note.get('archived', False) and not config['include_archived']:
            continue
        if any(needle in normalize(note.get(field, ''))
               for field in config['search_fields']):
            matches.append(note['id'])
    return matches[:config['max_results']]
